SELECT o.channel, CASE WHEN o.shipping_fee >= 31 THEN 'high' WHEN o.shipping_fee >= 11 THEN 'mid' ELSE 'low' END shipping_fee_bucket, ROUND(AVG(p.amount), 2) avg_amount, SUM(p.amount) total_amount FROM payments p INNER JOIN orders o ON p.order_id = o.id INNER JOIN customers c ON c.id = o.customer_id WHERE c.signup_date BETWEEN '2023-12-01' AND '2024-02-06' GROUP BY o.channel, CASE WHEN o.shipping_fee >= 31 THEN 'high' WHEN o.shipping_fee >= 11 THEN 'mid' ELSE 'low' END HAVING avg_amount > 24
